result.query:
SELECT gender AS gender, COUNT(*) AS count 
FROM public."FCC 2018 Survey" GROUP BY gender 
 LIMIT 10000;

SELECT CASE WHEN is_software_dev = 0 THEN 'Aspiring Developer' WHEN is_software_dev = 1 THEN 'Currently A Developer' END AS developer_type, COUNT(*) AS count 
FROM public."FCC 2018 Survey" GROUP BY CASE WHEN is_software_dev = 0 THEN 'Aspiring Developer' WHEN is_software_dev = 1 THEN 'Currently A Developer' END ORDER BY count DESC 
 LIMIT 10000;

SELECT COUNT(*) AS count, count(country_live) AS "COUNT(country_live)" 
FROM public."FCC 2018 Survey" 
 LIMIT 50000;

SELECT age AS age 
FROM public."FCC 2018 Survey" 
 LIMIT 10000;

